:root {
  --bg: #1a1c2c;
  --card: #2a2e45;
  --text: #f0f4ff;
  --muted: #8a93b8;
  --accent: #6ee7b7;
  --accent-dark: #34d399;
  --danger: #f87171;
  --warn: #fbbf24;
  --radius: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  background: radial-gradient(circle at 50% 20%, #262a44 0%, var(--bg) 70%);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  min-height: 100vh;
}

.card {
  width: 100%;
  max-width: 460px;
  background: var(--card);
  border: 2px solid #3b4266;
  border-radius: var(--radius);
  padding: 28px 24px 24px;
  box-shadow: 0 12px 0 #14162a, 0 24px 40px rgba(0,0,0,0.45);
}

.title {
  margin: 0 0 20px;
  text-align: center;
  font-size: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.display {
  font-size: clamp(40px, 12vw, 64px);
  font-weight: 700;
  text-align: center;
  letter-spacing: 2px;
  padding: 18px 8px;
  margin-bottom: 22px;
  background: #14162a;
  border-radius: 10px;
  border: 2px solid #3b4266;
  color: var(--accent);
  text-shadow: 0 0 12px rgba(110, 231, 183, 0.35);
  font-variant-numeric: tabular-nums;
  user-select: none;
}

.controls {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}

.btn {
  font-family: inherit;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 1px;
  padding: 14px 12px;
  border-radius: 10px;
  border: 2px solid transparent;
  cursor: pointer;
  color: #14162a;
  background: var(--accent);
  transition: transform 0.08s ease, background 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 4px 0 var(--accent-dark);
}

.btn:hover:not(:disabled) { background: #8af0c6; }
.btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}
.btn:active:not(:disabled) {
  transform: translateY(3px);
  box-shadow: 0 1px 0 var(--accent-dark);
}
.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

.btn.stop { background: var(--danger); box-shadow: 0 4px 0 #b91c1c; }
.btn.stop:hover:not(:disabled) { background: #fca5a5; }
.btn.stop:active:not(:disabled) { box-shadow: 0 1px 0 #b91c1c; }

.btn.lap { background: var(--warn); box-shadow: 0 4px 0 #b45309; }
.btn.lap:hover:not(:disabled) { background: #fcd34d; }
.btn.lap:active:not(:disabled) { box-shadow: 0 1px 0 #b45309; }

.btn.reset { background: var(--muted); box-shadow: 0 4px 0 #5b648a; }
.btn.reset:hover:not(:disabled) { background: #a5aed4; }
.btn.reset:active:not(:disabled) { box-shadow: 0 1px 0 #5b648a; }

.laps {
  border-top: 2px dashed #3b4266;
  padding-top: 18px;
}

.laps-title {
  margin: 0 0 12px;
  font-size: 15px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
}

.lap-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 200px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.lap-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background: #14162a;
  border-radius: 8px;
  border-left: 4px solid var(--accent);
  font-size: 16px;
  font-variant-numeric: tabular-nums;
}

.lap-list li .lap-num {
  color: var(--muted);
  font-size: 14px;
  letter-spacing: 1px;
}

.lap-list li .lap-time { color: var(--text); font-weight: 700; }

.empty {
  margin: 0;
  color: var(--muted);
  font-size: 15px;
  text-align: center;
  padding: 6px 0;
}

.empty.hidden { display: none; }

@media (max-width: 380px) {
  .card { padding: 22px 16px 18px; }
  .btn { font-size: 15px; padding: 12px 8px; }
  .title { font-size: 17px; }
}

(function () {
  'use strict';

  const display = document.getElementById('display');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');
  const lapBtn = document.getElementById('lapBtn');
  const resetBtn = document.getElementById('resetBtn');
  const lapList = document.getElementById('lapList');
  const emptyLaps = document.getElementById('emptyLaps');

  let startTime = 0;
  let elapsed = 0;
  let running = false;
  let rafId = null;
  let laps = [];

  function format(ms) {
    if (ms < 0) ms = 0;
    const totalCs = Math.floor(ms / 10);
    const cs = totalCs % 100;
    const totalSec = Math.floor(totalCs / 100);
    const sec = totalSec % 60;
    const min = Math.floor(totalSec / 60);
    return (
      String(min).padStart(2, '0') + ':' +
      String(sec).padStart(2, '0') + '.' +
      String(cs).padStart(2, '0')
    );
  }

  function currentElapsed() {
    return running ? elapsed + (performance.now() - startTime) : elapsed;
  }

  function render() {
    display.textContent = format(currentElapsed());
    if (running) {
      rafId = requestAnimationFrame(render);
    }
  }

  function setRunningUI(isRunning) {
    startBtn.disabled = isRunning;
    stopBtn.disabled = !isRunning;
    lapBtn.disabled = !isRunning;
    resetBtn.disabled = isRunning || (elapsed === 0 && laps.length === 0);
  }

  function start() {
    if (running) return;
    running = true;
    startTime = performance.now();
    setRunningUI(true);
    rafId = requestAnimationFrame(render);
  }

  function stop() {
    if (!running) return;
    elapsed = currentElapsed();
    running = false;
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    display.textContent = format(elapsed);
    setRunningUI(false);
  }

  function lap() {
    if (!running) return;
    const t = currentElapsed();
    laps.push(t);
    const li = document.createElement('li');
    const num = document.createElement('span');
    num.className = 'lap-num';
    num.textContent = 'Lap ' + laps.length;
    const time = document.createElement('span');
    time.className = 'lap-time';
    time.textContent = format(t);
    li.appendChild(num);
    li.appendChild(time);
    lapList.prepend(li);
    emptyLaps.classList.add('hidden');
  }

  function reset() {
    if (running) return;
    elapsed = 0;
    laps = [];
    lapList.innerHTML = '';
    emptyLaps.classList.remove('hidden');
    display.textContent = format(0);
    setRunningUI(false);
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);
  lapBtn.addEventListener('click', lap);
  resetBtn.addEventListener('click', reset);

  document.addEventListener('keydown', function (e) {
    if (e.target && (e.target.tagName === 'BUTTON' || e.target.tagName === 'INPUT')) return;
    if (e.code === 'Space') {
      e.preventDefault();
      if (running) stop(); else start();
    } else if (e.key === 'l' || e.key === 'L') {
      lap();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    }
  });

  setRunningUI(false);
  display.textContent = format(0);
})();
